/* @socom-skeleton stub Recoil__5CZKitFP11CZFTSWeapon */
void CZKit::Recoil(CZFTSWeapon *weapon)
{
	/* 0x2ab910 (Fire): the player's pad rumbles; unscoped, a burst past two rounds kicks the
	 * reticule up, the knock offset is held within the stance's max (y scaled by the aim
	 * depth), the reticule grows by the knock within the size limits and the body recoils */
	/* @socom-skeleton stub basebump_y$3108 */
	static int basebump_y;
	/* @socom-skeleton stub randbump_y$3111 */
	static int randbump_y;
	/* @socom-skeleton stub basebump_x$3114 */
	static int basebump_x;
	/* @socom-skeleton stub randbump_x$3117 */
	static int randbump_x;
	CEntityCtrl *ctrl = m_body->m_control;
	bool player = ctrl != NULL && ((CSealCtrl *)ctrl)->IsPlayer();

	if (!player)
		return;

	CTargetMods *mods = weapon->TargetMods((s32)m_body->GetStance(false));
	f32 knock = mods->GetReticuleKnock();
	f32 most = mods->GetReticuleKnock_Max();
	f32 min = mods->GetTarget_Min();
	f32 max = mods->GetTarget_Max();

	if (weapon->GetRumbleHigh_Enable())
		((CSealCtrl *)m_body->m_control)->SetHighRumbleTime(weapon->GetRumbleHigh_Time());

	if (weapon->GetRumbleLow_Enable())
		((CSealCtrl *)m_body->m_control)->SetLowRumbleTime(weapon->GetRumbleLow_Time(), weapon->GetRumbleLow_Power());

	ZOOMSTATE zoom = m_body->m_zoomstate;

	if (!((int)zoom < (int)ZOOMSTATE::ZOOMSTATE_WEAPONDEF1 && zoom != ZOOMSTATE::ZOOMSTATE_BINOCS))
		return;

	if (m_burst_count > 2)
		m_retoffsety -= knock;

	zdb::CCamera *camera = zdb::CWorld::m_world->m_camera;
	f32 aspecty = camera->m_screenAspect.y;
	f32 aspectx = camera->m_screenAspect.x;
	CZSealBody *seal = ftsGetPlayer();
	CPnt3D aim = seal->m_aim_point;
	CPnt3D fire;
	seal->m_curr_firepos.Add(seal->GetPosW(), &fire);
	f32 za = camera->GetZ(&aim);
	f32 zf = camera->GetZ(&fire);

	if (za - zf != 0.0f)
		aspecty = (aspecty * (za - zf)) / za;

	f32 limitx = most * aspectx;
	f32 limity = most * aspecty;

	/* ELF: the bump statics are set once (10, 20, 15, 10) and never read */
	basebump_y = 0x41200000;
	randbump_y = 0x41a00000;
	basebump_x = 0x41700000;
	randbump_x = 0x41200000;
	*(f32 *)&recoil_constscl = aspecty;

	if (limity < m_retoffsety)
		m_retoffsety = limity;
	else if (m_retoffsety < -limity)
		m_retoffsety = -limity;

	if (limitx < m_retoffsetx)
		m_retoffsetx = limitx;
	else if (m_retoffsetx < -limitx)
		m_retoffsetx = -limitx;

	m_prev_retsize = m_retsize;
	m_retsize += knock;

	if (m_retsize < min)
		m_retsize = min;
	else if (max < m_retsize)
		m_retsize = max;

	m_body->m_recoilParam += 1.0f;

	if (m_body->m_recoilParam > 1.0f)
		m_body->m_recoilParam = 1.0f;
}

/* @socom-skeleton stub Reload__5CZKitFv */
bool CZKit::Reload()
{
	/* 0x2ab530 (R3, an empty trigger): not airborne, dead, throwing or reloading. The next
	 * loaded mag (the grenade slot's in a launcher grenade mode) after the current one is
	 * put in with the reload anim and sound; none left: in a network game a pistol gets a
	 * full mag. The HUD refreshes; true when reloading. */
	CZSealBody *body = m_body;

	if (body == NULL || body->m_airborne || !body->m_isAlive || body->IsThrowing(false) || m_body->IsReloading())
		return false;

	s32 index = m_selected_item;
	s32 slot = unwrap(index, m_num_items);
	s32 wrapped = unwrap(slot, m_num_items);
	CZFTSWeapon *weapon = wrapped != -1 ? m_item[wrapped] : NULL;

	if (weapon != NULL && weapon->IsGrenadeLauncherWeapon() && m_firemode[slot] >= 4)
		index = m_firemode[m_selected_item] - 3;

	bool loaded = false;

	if (index < m_num_items)
	{
		for (s32 j = 0; j < 10; j++)
		{
			if (m_reloads[index][j] > 0)
			{
				loaded = true;
				break;
			}
		}
	}

	if (!loaded)
	{
		if (!theNetwork.m_bNetwork || m_item[index]->GetIDType() != EQUIP_ITEM::EQUIP_PISTOL)
			return false;

		m_reloads[index][m_currentmag[index]] = m_item[index]->GetAmmoCapacity();

		if (m_body->Reload() == NULL)
			return false;

		if (m_item[index]->m_reloadsound != NULL)
			m_item[index]->m_reloadsound->PlaySound(NULL, 0xff);

		m_weaponinfoChanged = 1;
		return true;
	}

	s32 mag = m_currentmag[index] + 1;

	if (mag > 9)
		mag = 0;

	bool found = false;

	while (mag != m_currentmag[index] && !found)
	{
		if (m_reloads[index][mag] < 1)
		{
			mag++;

			if (mag > 9)
				mag = 0;
		}
		else
		{
			found = true;
		}
	}

	if (found)
	{
		if (m_body->Reload() == NULL)
			return false;

		m_currentmag[index] = mag;

		if (m_item[index]->m_reloadsound != NULL)
			m_item[index]->m_reloadsound->PlaySound(NULL, 0xff);
	}
	else if (theNetwork.m_bNetwork && m_item[index]->GetIDType() == EQUIP_ITEM::EQUIP_PISTOL)
	{
		m_reloads[index][m_currentmag[index]] = m_item[index]->GetAmmoCapacity();

		if (m_body->Reload() == NULL)
			return false;

		if (m_item[index]->m_reloadsound != NULL)
			m_item[index]->m_reloadsound->PlaySound(NULL, 0xff);
	}

	m_weaponinfoChanged = 1;
	return true;
}

/* @socom-skeleton stub TickReticule__5CZKitFf */
void CZKit::TickReticule(float dT)
{
	/* 0x2ab220: the player's reticule knock returns toward the centre; its size goal grows
	 * with speed (velM^2 / 65, turn rate^2 x 5.29 x 30, air speed^2 / 65) between the size
	 * limits and the size follows it at the stance's constrict rate */
	CEntityCtrl *ctrl = m_body->m_control;
	bool player = ctrl != NULL && ((CSealCtrl *)ctrl)->IsPlayer();
	CZFTSWeapon *weapon = player ? dynamic_cast<CZFTSWeapon *>((CZWeapon *)m_item[m_selected_item]) : NULL;

	if (weapon == NULL)
		return;

	CTargetMods *mods = weapon->TargetMods((s32)m_body->GetStance(false));
	f32 back = mods->GetReticuleKnock_Return() * dT;

	if (m_retoffsetx > 0.0f)
	{
		m_retoffsetx -= back;

		if (m_retoffsetx < 0.0f)
			m_retoffsetx = 0.0f;
	}

	if (m_retoffsetx < 0.0f)
	{
		m_retoffsetx += back;

		if (m_retoffsetx > 0.0f)
			m_retoffsetx = 0.0f;
	}

	if (m_retoffsety > 0.0f)
	{
		m_retoffsety -= back;

		if (m_retoffsety < 0.0f)
			m_retoffsety = 0.0f;
	}

	if (m_retoffsety < 0.0f)
	{
		m_retoffsety += back;

		if (m_retoffsety > 0.0f)
			m_retoffsety = 0.0f;
	}

	CZSealBody *body = m_body;
	f32 goal = (body->m_velM.z * body->m_velM.z + body->m_velM.x * body->m_velM.x + body->m_velM.y * body->m_velM.y) * 0.015384615f
		+ (body->m_velR.z * body->m_velR.z + body->m_velR.x * body->m_velR.x + body->m_velR.y * body->m_velR.y) * 5.29f * 30.0f;

	if (body->m_airborne)
	{
		goal += (body->m_inAirHorizVel.z * body->m_inAirHorizVel.z + body->m_inAirHorizVel.x * body->m_inAirHorizVel.x
			+ body->m_inAirHorizVel.y * body->m_inAirHorizVel.y) * 0.015384615f;
	}

	if (goal < m_retmin)
		m_retsizegoal = m_retmin;
	else if (m_retmax < goal)
		m_retsizegoal = m_retmax;
	else
		m_retsizegoal = goal;

	if (m_item[m_selected_item] == NULL)
		return;

	f32 rate = mods->GetTarget_Constrict();
	m_prev_retsize = m_retsize;
	f32 size = m_retsize;

	if (size < m_retsizegoal)
	{
		m_retsize = size + rate * dT;

		if (m_retsizegoal < m_retsize)
			m_retsize = m_retsizegoal;
	}
	else if (m_retsizegoal < size)
	{
		m_retsize = size - rate * dT;

		if (m_retsize < m_retsizegoal)
			m_retsize = m_retsizegoal;
	}
}

/* port: file-local helpers for TickExplosives' throw. CDynGrenade (no DWARF class; inline
 * members emitted out of line next to CSealCtrl::PostTick, which draws the same throw line)
 * and the ai:: templates _saturate<f> 0x1a8dd0 / _max<f> 0x26c8a0 are not declared in src/;
 * their bodies follow the ELF. */
namespace
{
/* _saturate<f>: clamp into [lo, hi] (the ELF returns whether it clamped; unused here) */
inline void throw_saturate(f32 *value, const f32 &lo, const f32 &hi)
{
	if (!(*value <= hi))
		*value = hi;
	else if (*value < lo)
		*value = lo;
}

/* _max<f> */
inline const f32 &throw_max(const f32 &a, const f32 &b)
{
	return a < b ? b : a;
}

/* CDynGrenade::ComputeMaxVel 0x2879f0: the speed that carries a 45 degree throw `dist`
 * far from `height` (g = 98); the flight time out */
f32 DynGrenadeComputeMaxVel(f32 dist, f32 height, f32 *time)
{
	static const f32 tan_45 = 1.0f;       /* tan_45$localstatic3 */
	static const f32 cos_45 = 0.70710725f; /* cos_45$localstatic5 (0x3f3504f7) */
	f32 t = sqrtf(2.0f * (height + tan_45 * dist) / 98.0f);
	f32 speed = dist / (cos_45 * t);

	if (time != NULL)
		*time = t;

	return speed;
}

/* CDynGrenade::ComputeElevOfs 0x287980: 10 to 12 degrees more elevation with the power */
f32 DynGrenadeComputeElevOfs(f32 power)
{
	static const f32 elev_offset_min = 10.0f; /* elev_offset_min$localstatic3 */
	static const f32 elev_offset_max = 12.0f; /* elev_offset_max$localstatic5 */
	return 0.017453292f * (elev_offset_min * (1.0f - power) + elev_offset_max * power);
}

/* CDynGrenade::Initalize's elevation limits (min_elev 0x452ff8, max_elev 0x453000) and
 * do_adjust (true) */
const f32 throw_min_elev = 0.0f;
const f32 throw_max_elev = 0.95993114f; /* 0x3f75be0b: 55 degrees */
const f32 throw_min_speed = 0.0f;       /* @2331 0x475034 */
}

/* @socom-skeleton stub TickExplosives__5CZKitFf */
bool CZKit::TickExplosives(float dT)
{
	/* 0x2aa7a0 (Tick): a remote seal goes on (1). A local one with an item: a pending
	 * placement / throw counts down its fire time; when it runs out C4, claymores, satchels
	 * and the MP bomb are placed (false: nothing else this frame) and a throwable's round is
	 * thrown. Otherwise true; no item: false. */
	/* @socom-skeleton stub r_offset$3288 */
	static float r_offset[3];
	/* @socom-skeleton stub l_offset$3291 */
	static float l_offset[3];
	/* @socom-skeleton stub can_fire$3296 */
	static unsigned char can_fire = 1; /* set to 1 on first use (init$3297) and never changed */
	CEntityCtrl *ctrl = m_body->m_control;

	if (ctrl != NULL && ((CSealCtrl *)ctrl)->IsRemote())
		return true;

	if (m_item[m_selected_item] == NULL)
		return false;

	bool c4 = false;
	bool placed = false;
	bool thrown = false;

	if (m_waiting_to_fire && m_firetime >= 0.0f)
		m_firetime -= dT;

	if (m_waiting_to_fire && m_firetime <= 0.0f)
	{
		EQUIP_ITEM id = m_item[m_selected_item]->m_ID;

		if (id == EQUIP_ITEM::CLAYMORE || id == EQUIP_ITEM::SATCHEL_CHARGE || id == EQUIP_ITEM::MPBOMB)
			placed = true;
		else if (id == EQUIP_ITEM::C4)
			c4 = true;
		else
			thrown = true;

		m_waiting_to_fire = 0;
		m_firetime = 0.0f;
	}

	if (c4 || placed)
	{
		/* port: not written - the C4 wall placement (a 16-unit probe along the aim from the
		 * right hand, the material checks, HandleRemotePlaceExplosive) and the claymore /
		 * satchel / MP bomb ground placement (GetAltitude below the hand, then
		 * HandleRemotePlaceExplosive); both restore the last selected item. The ELF returns
		 * false for C4 and for a placement on the ground (true without ground). */
		(void)r_offset;
		(void)l_offset;
		return false;
	}

	if (thrown)
	{
		m_burst_count++;

		if (!m_body->m_infiniteammo)
		{
			s32 slot = unwrap(m_selected_item, m_num_items);
			m_weaponinfoChanged = 1;

			if (m_reloads[slot][m_currentmag[slot]] > 0)
				m_reloads[slot][m_currentmag[slot]]--;
		}

		m_fire_delay = 0.0f;
		/* 0x2aad5c: the release point: (2, 0, 0) in the throwing hand (the left one for the
		 * left lean toss), in body space. ELF: both hands use r_offset. */
		r_offset[0] = 2.0f;
		r_offset[1] = 0.0f;
		r_offset[2] = 0.0f;
		l_offset[0] = 2.0f;
		l_offset[1] = 0.0f;
		l_offset[2] = 0.0f;
		CZBodyPart *hand = m_body->m_rhand;

		if (m_body->IsCurrentBlend((AnimType)AnimTypes::TossGrenadePeekLeft))
			hand = m_body->m_lhand;

		CPnt3D release = CPnt3D::zero;
		m_body->PartInSpace(hand, reinterpret_cast<const CPnt3D *>(r_offset), &release, NULL);

		if (can_fire)
		{
			const throw_params &params = m_body->GetDynamics()->m_throw_params;
			f32 reach = m_body->m_state == 0 ? params.max_distance_stand : params.max_distance_crouch;
			CEntityCtrl *thrower = m_body->m_control;

			if (thrower != NULL && ((CSealCtrl *)thrower)->IsPlayer())
			{
				/* the player: CDynGrenade::Initalize inlined. The 45 degree speed for the
				 * stance's reach from the hand's height; the elevation from the aim (0 to 55
				 * degrees) plus 10..12 by power; the speed from 30% (no power) to 100% of it;
				 * the flight time to the ground and so the reach; the throw turned from the
				 * hand toward the point that far ahead and elevated, and (ELF quirk kept) its
				 * speed becomes the hand's horizontal distance to that point, at most the
				 * 45 degree speed. Into world space, then thrown. */
				f32 power = ((CSealCtrl *)thrower)->m_trigger_power;
				f32 height = release.y;
				zdb::CNode *node = m_body->m_node;
				f32 time = 0.0f;
				f32 maxvel = DynGrenadeComputeMaxVel(reach, height, &time);
				f32 elev = asinf(m_body->m_aim_goal.y);
				throw_saturate(&elev, throw_min_elev, throw_max_elev);
				elev += DynGrenadeComputeElevOfs(power);
				f32 s = sinf(elev);
				f32 c = cosf(elev);
				f32 speed = 0.3f * maxvel * (1.0f - power) + maxvel * power;
				f32 r1;
				f32 r2;
				f32 t = ai::quadratic(0.5f * -98.0f, speed * s, height, r1, r2) ? throw_max(r1, r2) : 0.0f;
				f32 dist = speed * c * t;
				CPnt3D dir;
				/* do_adjust$localstatic5 is set on first use and never cleared */
				speed = sqrtf(release.x * release.x + release.z * release.z + dist * dist + 2.0f * dist * release.z);
				throw_saturate(&speed, throw_min_speed, maxvel);
				dir.x = -release.x;
				dir.y = 0.0f;
				dir.z = -(dist + release.z);
				dir.Normalize();
				ai::elevate(dir, s, c);
				node->m_matrix.Rotate(&dir, &dir, 1);
				CPnt3D from;
				node->m_matrix.Transform(&release, &from, 1);
				dir.Scale(speed, &dir);
				((CSealCtrl *)thrower)->TriggerPowerReset();
#ifdef SOCOM_PORT
				SOCOM_PORT_TRACE("GREN: throw params abort %.2f stand %.1f crouch %.1f toss power %.2f aim %.2f, stance %d, hand %.1f %.1f %.1f",
					params.m_abort_threshold, params.max_distance_stand, params.max_distance_crouch, params.toss_power_threshold,
					params.toss_aim_threshold, (s32)m_body->m_state, release.x, release.y, release.z);
				SOCOM_PORT_TRACE("GREN: thrown by %s: power %.2f, reach %.1f, elevation %.1f deg, speed %.1f (45 deg %.1f), from %.1f %.1f %.1f, vel %.1f %.1f %.1f",
					node->m_name != NULL ? node->m_name : "-", power, reach, elev * 57.29578f, speed, maxvel, from.x, from.y, from.z, dir.x, dir.y, dir.z);
#endif
				Fire(m_selected_item, &from, &dir, &CPnt3D::zero);
			}
			else if (thrower != NULL && ((CSealCtrl *)thrower)->IsAi())
			{
				/* port: not written - an AI thrower (the release point into world space,
				 * CSealCtrlAi::UpdateThrowFireParams, Fire along the fire params' throw
				 * vector, the params' throw flag and power cleared); enemy throws are out of
				 * scope */
			}

			if (m_last_selected >= 0)
			{
				SetCurItemByIndex(m_last_selected);
				m_last_selected = -1;
			}
		}
	}

	return true;
}

