	CZFTSWeapon *weapon = slot != -1 ? m_item[slot] : NULL;

	if (weapon == NULL || (!weapon->IsM203Weapon() && !weapon->IsGrenadeLauncherWeapon()) || mode < 4)
		return ItemHasAmmo(index);

	return ItemHasAmmo(mode - 3);
