void CZKit::UpdateNumItems()
{
	/* 0x2a57b0: past the last used slot; an empty or out-of-range selection goes to 0 */
	s32 last = -1;

	for (s32 i = 0; i < 30; i++)
	{
		if (m_item[i] != NULL)
			last = i;
	}

	m_num_items = last + 1;

	if (m_num_items < m_selected_item || m_item[m_selected_item] == NULL)
	{
		m_selected_item = 0;
		m_weaponinfoChanged = 1;
	}
}

